// ABI compatibility: the frontend's transaction builders, RPC view calls and
// view types against the cargo-near ABI of the real contract build.
//
// Fixture: apps/web/fixtures/contract-main/abi/linefair_escrow_abi.json,
// generated by `cargo near build non-reproducible-wasm --locked` from main
// 8ec0816 (lf-012 f3) exported with `git archive`; WASM sha256
// 470db97b62cd04701e68f6a87d7589dd8af9b8d122b96e4f5e12788d4405f2e1
// (MANIFEST.json, evidence/frontend/main-wasm-abi-build-*.log.txt).
// This proves name/type agreement with the ABI only, not chain behaviour.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import {
  acceptAppointmentCall,
  acceptLineCall,
  acceptSplitCall,
  acceptTermsCall,
  advanceCaseCall,
  createAgreementCall,
  fundLineCall,
  openDisputeCall,
  proposeSplitCall,
  submitDeliveryCall,
  submitRulingCall,
  triggerFallbackCall,
  withdrawCall,
  GAS,
  ONE_YOCTO,
  WITHDRAW_MIN_GAS,
  type FunctionCallSpec,
} from "./tx.ts";
import { NearRpc, type FetchFn } from "./rpc.ts";
import {
  AGREEMENT_VIEW_FIELDS,
  CONFIG_VIEW_FIELDS,
  CUSTODY_SUMMARY_VIEW_FIELDS,
  LINE_VIEW_FIELDS,
  WITHDRAWAL_RESULT_VIEW_FIELDS,
  WITHDRAWAL_VIEW_FIELDS,
} from "../contract/types.ts";
import { LINE_KEYS, TERMS_KEYS } from "../terms.ts";

type Schema = { type?: string | string[]; format?: string; $ref?: string; anyOf?: Schema[]; properties?: Record<string, Schema>; required?: string[] };
interface AbiFn {
  name: string;
  kind: "view" | "call";
  modifiers?: string[];
  params?: { serialization_type: string; args: { name: string; type_schema: Schema }[] };
  result?: { serialization_type: string; type_schema: Schema };
}

const FIXTURE = new URL("../../../fixtures/contract-main/", import.meta.url);
const ABI = JSON.parse(readFileSync(new URL("abi/linefair_escrow_abi.json", FIXTURE), "utf8")) as {
  metadata: { name: string; wasm_hash: string };
  body: { functions: AbiFn[]; root_schema: { definitions: Record<string, Schema> } };
};
const FNS = new Map(ABI.body.functions.map((f) => [f.name, f]));
const DEFS = ABI.body.root_schema.definitions;

const H = "9257a5bfea49918f0a1b1a3308ad553a384079e73da987df495f55002869a33c";
const E = "escrow.test.near";

/** Value conforms to the (shallow) ABI schema. Refs resolve to object definitions with required keys. */
function conforms(v: unknown, s: Schema): boolean {
  if (s.$ref !== undefined) {
    const def = DEFS[s.$ref.replace("#/definitions/", "")];
    if (def === undefined || typeof v !== "object" || v === null) return false;
    return (def.required ?? []).every((k) => k in (v as object));
  }
  if (s.anyOf !== undefined) return s.anyOf.some((x) => conforms(v, x));
  const types = Array.isArray(s.type) ? s.type : [s.type];
  return types.some((t) => {
    switch (t) {
      case "string":
        return typeof v === "string";
      case "null":
        return v === null;
      case "integer":
        if (typeof v !== "number" || !Number.isInteger(v) || v < 0) return false;
        return s.format === "uint32" ? v <= 0xffff_ffff : Number.isSafeInteger(v);
      case "boolean":
        return typeof v === "boolean";
      default:
        return false;
    }
  });
}

function assertMatchesAbi(spec: FunctionCallSpec, expectedKind: "call" | "view" = "call"): void {
  const f = FNS.get(spec.methodName);
  assert.ok(f, `${spec.methodName} is not in the contract ABI`);
  assert.equal(f.kind, expectedKind, `${spec.methodName} kind`);
  const mods = f.modifiers ?? [];
  assert.ok(!mods.includes("private") && !mods.includes("init"), `${spec.methodName} is private/init`);
  // Not payable in the ABI -> the builder must attach 0 (attached NEAR would be rejected).
  if (!mods.includes("payable")) assert.equal(spec.deposit, 0n, `${spec.methodName} deposit`);
  const abiArgs = f.params?.args ?? [];
  assert.deepEqual(Object.keys(spec.args), abiArgs.map((a) => a.name), `${spec.methodName} argument names/order`);
  assert.equal(f.params?.serialization_type ?? "json", "json");
  for (const a of abiArgs) {
    assert.ok(conforms(spec.args[a.name], a.type_schema), `${spec.methodName}.${a.name}=${JSON.stringify(spec.args[a.name])} vs ${JSON.stringify(a.type_schema)}`);
  }
}

const TERMS_SAMPLE = Object.fromEntries(TERMS_KEYS.map((k) => [k, k === "lines" ? [] : "x"]));

/** One builder per public non-init, non-receiver call method. */
const BUILT: Record<string, FunctionCallSpec> = {
  create_agreement: createAgreementCall(E, TERMS_SAMPLE as never),
  accept_terms: acceptTermsCall(E, "0", H),
  accept_appointment: acceptAppointmentCall(E, "0", H),
  submit_delivery: submitDeliveryCall(E, "0", 1, H),
  accept_line: acceptLineCall(E, "0", 1),
  open_dispute: openDisputeCall(E, "0", 1),
  advance_case: advanceCaseCall(E, "0", 1),
  propose_split: proposeSplitCall(E, "0", 1, 300n, 700n, 1000n),
  accept_split: acceptSplitCall(E, "0", 1, "1", "300", "700"),
  submit_ruling: submitRulingCall(E, "0", 1, 300n, 700n, 1000n),
  trigger_fallback: triggerFallbackCall(E, "0", 1),
  withdraw: withdrawCall(E, "0", 1, "SUPPLIER"),
};

test("ABI fixture is the main 8ec0816 build (wasm sha256 470db97b…f2e1)", () => {
  assert.equal(ABI.metadata.name, "linefair-escrow");
  // bs58 of sha256 470db97b62cd04701e68f6a87d7589dd8af9b8d122b96e4f5e12788d4405f2e1 (cargo-near output)
  assert.equal(ABI.metadata.wasm_hash, "5nN5ua65yntBYmNZC6JEtdWYBbbuBkVxuHC7GZxpBgcQ");
  const manifest = JSON.parse(readFileSync(new URL("MANIFEST.json", FIXTURE), "utf8")) as { wasm_sha256: string };
  assert.equal(manifest.wasm_sha256, "470db97b62cd04701e68f6a87d7589dd8af9b8d122b96e4f5e12788d4405f2e1");
});

test("LF-010A: new takes creator_allowlist last; ConfigView.creator_allowlist is a required array of account ids", () => {
  const n = FNS.get("new");
  assert.deepEqual(n?.modifiers, ["init", "private"]); // only the contract account itself, in the deploy transaction
  assert.deepEqual(n?.params?.args.map((a) => a.name), ["network_id", "allowlisted_ft_id", "operator_treasury_id", "max_agreements", "creator_allowlist"]);
  const p = DEFS.ConfigView?.properties?.creator_allowlist as { type?: string; items?: { type?: string } } | undefined;
  assert.equal(p?.type, "array");
  assert.equal(p?.items?.type, "string");
  assert.ok(DEFS.ConfigView?.required?.includes("creator_allowlist"));
  // create_agreement signature unchanged (the gate is a caller check, not an argument)
  assert.deepEqual(FNS.get("create_agreement")?.params?.args.map((a) => a.name), ["terms"]);
  // no method other than init can write the list: no new call method appeared
  assert.ok(!ABI.body.functions.some((f) => /allowlist|creator/i.test(f.name)));
});

test("every builder matches its ABI method: name, kind, payability, arg names, order and JSON types", () => {
  for (const [name, spec] of Object.entries(BUILT)) {
    assert.equal(spec.methodName, name);
    assert.equal(spec.receiverId, E);
    assertMatchesAbi(spec);
  }
});

test("every public call method in the ABI has a builder (except init and the NEP-141 receiver)", () => {
  const calls = ABI.body.functions
    .filter((f) => f.kind === "call" && !(f.modifiers ?? []).includes("init") && !(f.modifiers ?? []).includes("private"))
    .map((f) => f.name)
    .filter((n) => n !== "ft_on_transfer");
  assert.deepEqual(calls.sort(), Object.keys(BUILT).sort());
  // the private LF-009 callback is never built by the UI
  assert.deepEqual(FNS.get("on_withdrawal_transfer")?.modifiers, ["private"]);
});

test("LF-009 withdraw: the only payable escrow method; exactly 1 yoctoNEAR and 100 Tgas >= the lib.rs floor", () => {
  const payable = ABI.body.functions.filter((f) => (f.modifiers ?? []).includes("payable")).map((f) => f.name);
  assert.deepEqual(payable, ["withdraw"]);
  for (const [name, spec] of Object.entries(BUILT)) {
    if (name !== "withdraw") assert.equal(spec.deposit, 0n, name);
  }
  const w = withdrawCall(E, "12", 2, "BUYER");
  assert.equal(w.receiverId, E);
  assert.equal(w.deposit, ONE_YOCTO);
  assert.equal(w.deposit, 1n);
  assert.equal(w.gas, 100_000_000_000_000n);
  assert.equal(w.gas, GAS.withdraw);
  assert.deepEqual(w.args, { agreement_id: "12", line_id: 2, beneficiary: "BUYER" });
  // re-derive the floor from the release constants in lib.rs (not the test-starve-callback ones)
  const lib = readFileSync(new URL("src/lib.rs", FIXTURE), "utf8");
  const tgas = (name: string) => {
    const m = new RegExp(`#\\[cfg\\(not\\(feature = "test-starve-callback"\\)\\)\\]\\s*pub const ${name}: Gas = Gas::from_tgas\\((\\d+)\\);|\\npub const ${name}: Gas = Gas::from_tgas\\((\\d+)\\);`).exec(lib);
    assert.ok(m, `${name} not found`);
    return BigInt(m[1] ?? m[2]) * 1_000_000_000_000n;
  };
  const floor = tgas("GAS_FT_TRANSFER") + tgas("GAS_WITHDRAW_CALLBACK") + tgas("GAS_WITHDRAW_SELF");
  assert.equal(floor, 55_000_000_000_000n);
  assert.equal(WITHDRAW_MIN_GAS, floor);
  assert.ok(w.gas >= floor);
  const args = FNS.get("withdraw")?.params?.args.map((a) => [a.name, a.type_schema.type, a.type_schema.format ?? null]);
  assert.deepEqual(args, [["agreement_id", "string", null], ["line_id", "integer", "uint32"], ["beneficiary", "string", null]]);
  assert.throws(() => withdrawCall(E, "0", 0, "buyer" as never), /BUYER or SUPPLIER/);
  assert.throws(() => withdrawCall(E, "0", 0, "" as never), /BUYER or SUPPLIER/);
  assert.throws(() => withdrawCall(E, "01", 0, "BUYER"), /canonical/);
  assert.throws(() => withdrawCall(E, "0", -1, "BUYER"));
});

test("LF-008 methods: exact ABI signature, non-payable, no result", () => {
  const r = FNS.get("submit_ruling");
  assert.deepEqual(
    r?.params?.args.map((a) => [a.name, a.type_schema.type, a.type_schema.format ?? null]),
    [["agreement_id", "string", null], ["line_id", "integer", "uint32"], ["buyer_amount", "string", null], ["supplier_amount", "string", null]],
  );
  assert.equal(r?.result, undefined);
  assert.deepEqual(r?.modifiers ?? [], []);
  const f = FNS.get("trigger_fallback");
  assert.deepEqual(
    f?.params?.args.map((a) => [a.name, a.type_schema.type, a.type_schema.format ?? null]),
    [["agreement_id", "string", null], ["line_id", "integer", "uint32"]],
  );
  assert.equal(f?.result, undefined);
  assert.deepEqual(f?.modifiers ?? [], []);
});

test("LF-007 split methods: exact ABI signature", () => {
  const p = FNS.get("propose_split");
  assert.deepEqual(
    p?.params?.args.map((a) => [a.name, a.type_schema.type, a.type_schema.format ?? null]),
    [["agreement_id", "string", null], ["line_id", "integer", "uint32"], ["buyer_amount", "string", null], ["supplier_amount", "string", null]],
  );
  assert.deepEqual(p?.result?.type_schema, { type: "string" }); // U64 proposal id
  const a = FNS.get("accept_split");
  assert.deepEqual(
    a?.params?.args.map((x) => [x.name, x.type_schema.type]),
    [["agreement_id", "string"], ["line_id", "integer"], ["proposal_id", "string"], ["buyer_amount", "string"], ["supplier_amount", "string"]],
  );
  assert.equal(a?.result, undefined);
});

test("builders refuse values the contract would reject on format", () => {
  assert.throws(() => proposeSplitCall(E, "0", 0, 1n, 1n, 3n), /principal/);
  assert.throws(() => proposeSplitCall(E, "0", 0, -1n, 4n, 3n));
  assert.throws(() => proposeSplitCall(E, "00", 0, 1n, 2n, 3n), /canonical/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "0", "1", "2"), /no proposal/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "01", "1", "2"), /canonical/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "1", "+1", "2"), /canonical/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "1", "1.0", "2"), /canonical/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "18446744073709551616", "1", "2"), /range/);
  assert.throws(() => acceptSplitCall(E, "0", 0, "1", (1n << 128n).toString(), "0"), /range/);
  assert.throws(() => acceptLineCall(E, "0", -1));
  assert.throws(() => acceptLineCall(E, "0", 1.5));
  assert.throws(() => submitDeliveryCall(E, "0", 0, H.toUpperCase()));
  assert.throws(() => submitRulingCall(E, "0", 0, 1n, 1n, 3n), /principal/);
  assert.throws(() => submitRulingCall(E, "0", 0, -1n, 4n, 3n));
  assert.throws(() => submitRulingCall(E, "0", 0, 1n << 128n, 0n, 1n << 128n), /range/);
  assert.throws(() => triggerFallbackCall(E, "01", 0), /canonical/);
  assert.throws(() => triggerFallbackCall(E, "0", -1));
  assert.deepEqual(submitRulingCall(E, "7", 2, 0n, 9n, 9n).args, { agreement_id: "7", line_id: 2, buyer_amount: "0", supplier_amount: "9" });
  assert.deepEqual(triggerFallbackCall(E, "7", 2).args, { agreement_id: "7", line_id: 2 });
  // zero legs are valid split amounts (founder S5 item 7: zero legs are skipped)
  assert.deepEqual(proposeSplitCall(E, "4", 2, 0n, 9n, 9n).args, { agreement_id: "4", line_id: 2, buyer_amount: "0", supplier_amount: "9" });
});

test("RPC view calls use ABI view names and argument names", async () => {
  const seen: { method_name: string; args: Record<string, unknown> }[] = [];
  const fn: FetchFn = async (_u, init) => {
    const p = (JSON.parse(init.body) as { params: { method_name: string; args_base64: string } }).params;
    seen.push({ method_name: p.method_name, args: JSON.parse(atob(p.args_base64)) as Record<string, unknown> });
    const bytes = [...new TextEncoder().encode('"0"')];
    return { ok: true, status: 200, text: async () => JSON.stringify({ jsonrpc: "2.0", id: "x", result: { result: bytes, logs: [], block_height: 1, block_hash: "h" } }) };
  };
  const rpc = new NearRpc("http://127.0.0.1:0", fn);
  await rpc.getConfig(E);
  await rpc.getAgreement(E, "3");
  await rpc.computeTermsHash(E, TERMS_SAMPLE);
  await rpc.outstandingLiabilities(E);
  await rpc.contractVersion(E);
  await rpc.getWithdrawal(E, "3", 1, "SUPPLIER");
  await rpc.getWithdrawal(E, "3", 1, "BUYER", 1n);
  await rpc.custodySummary(E, 1n);
  for (const s of seen) {
    const f = FNS.get(s.method_name);
    assert.ok(f, `${s.method_name} not in ABI`);
    assert.equal(f.kind, "view", s.method_name);
    const abiArgs = f.params?.args ?? [];
    assert.deepEqual(Object.keys(s.args), abiArgs.map((a) => a.name), s.method_name);
    for (const a of abiArgs) assert.ok(conforms(s.args[a.name], a.type_schema), `${s.method_name}.${a.name}`);
  }
  assert.equal(seen.length, 8);
});

test("snapshot reads query an exact block id, and a response from another block is rejected", async () => {
  const bodies: Record<string, unknown>[] = [];
  const answer = (height: number): FetchFn => async (_u, init) => {
    bodies.push((JSON.parse(init.body) as { params: Record<string, unknown> }).params);
    const bytes = [...new TextEncoder().encode("null")];
    return { ok: true, status: 200, text: async () => JSON.stringify({ jsonrpc: "2.0", id: "x", result: { result: bytes, logs: [], block_height: height, block_hash: "h" } }) };
  };
  await new NearRpc("http://127.0.0.1:0", answer(42)).getWithdrawal(E, "0", 0, "BUYER", 42n);
  assert.equal(bodies[0]?.block_id, 42);
  assert.equal("finality" in (bodies[0] ?? {}), false);
  await new NearRpc("http://127.0.0.1:0", answer(42)).getWithdrawal(E, "0", 0, "BUYER");
  assert.equal(bodies[1]?.finality, "final");
  await assert.rejects(new NearRpc("http://127.0.0.1:0", answer(43)).custodySummary(E, 42n), /asked for block 42, got 43/);
});

/** Required vs optional properties of an ABI object definition. */
function fields(def: string): { all: string[]; required: string[] } {
  const d = DEFS[def];
  assert.ok(d?.properties, `${def} missing in ABI`);
  return { all: Object.keys(d.properties).sort(), required: [...(d.required ?? [])].sort() };
}

test("view types list exactly the ABI fields (LineView incl. LF-007 allocation/proposal and LF-008 phase fields)", () => {
  const line = fields("LineView");
  assert.deepEqual([...LINE_VIEW_FIELDS].sort(), line.all);
  // the Option fields are the only non-required ones, and the ABI types them as string|null
  const optional = ["backup_start_ns", "fallback_start_ns", "no_response_t0_ns", "non_delivery_t0_ns", "primary_start_ns"];
  assert.deepEqual(line.all.filter((k) => !line.required.includes(k)), optional);
  for (const k of optional) assert.deepEqual(DEFS.LineView.properties?.[k]?.type, ["string", "null"]);
  assert.equal(DEFS.LineView.properties?.dispute_phase?.type, "string");
  assert.ok(line.required.includes("dispute_phase"));
  // every U64/U128 arrives as a JSON string; only line_id is a number
  for (const k of LINE_VIEW_FIELDS) {
    const t: Schema["type"] = DEFS.LineView.properties?.[k]?.type;
    if (k === "line_id") assert.equal(t, "integer");
    else assert.ok(t === "string" || (Array.isArray(t) && t.includes("string")), `${k}: ${JSON.stringify(t)}`);
  }
  assert.deepEqual([...AGREEMENT_VIEW_FIELDS].sort(), fields("AgreementView").all);
  assert.deepEqual([...CONFIG_VIEW_FIELDS].sort(), fields("ConfigView").all);
  assert.deepEqual([...TERMS_KEYS].sort(), fields("AgreementTermsJsonV1").all);
  assert.deepEqual([...LINE_KEYS].sort(), fields("LineTermsJsonV1").all);
});

test("LF-009 view types list exactly the ABI fields, all required; only line_id/epoch are integers", () => {
  for (const [def, list] of [
    ["WithdrawalView", WITHDRAWAL_VIEW_FIELDS],
    ["CustodySummaryView", CUSTODY_SUMMARY_VIEW_FIELDS],
    ["WithdrawalResultView", WITHDRAWAL_RESULT_VIEW_FIELDS],
  ] as const) {
    const f = fields(def);
    assert.deepEqual([...list].sort(), f.all, def);
    assert.deepEqual(f.required, f.all, `${def}: every field required`);
    for (const k of list) {
      const p = DEFS[def]?.properties?.[k];
      if (k === "line_id" || k === "epoch") assert.deepEqual([p?.type, p?.format], ["integer", "uint32"], `${def}.${k}`);
      else assert.equal(p?.type, "string", `${def}.${k}`);
    }
  }
});

