test("lifecycle builders used by the UI match the ABI (accept_terms, accept_appointment, submit_delivery, accept_line, open_dispute, advance_case)", () => {
  for (const spec of [
    acceptTermsCall(E, "18446744073709551615", H),
    acceptAppointmentCall(E, "0", H),
    submitDeliveryCall(E, "3", 2, "bbc32e833925fcdb50a7b4a82e0a033ca4ae76b2d7ffef3cd05b8cdcc1b42b7a"),
    acceptLineCall(E, "3", 0),
    openDisputeCall(E, "3", 1),
    advanceCaseCall(E, "3", 2),
  ]) {
    assertMatchesAbi(spec);
    assert.equal(spec.deposit, 0n, `${spec.methodName} must attach no NEAR`);
    assert.ok(spec.gas >= 30_000_000_000_000n);
  }
});

test("funding: ft_on_transfer ABI is (sender_id, amount, msg) and the v1 msg satisfies every funding.rs rule", () => {
  const f = FNS.get("ft_on_transfer");
  assert.ok(f, "ft_on_transfer in ABI");
  assert.deepEqual((f.params?.args ?? []).map((a) => a.name), ["sender_id", "amount", "msg"]);
  const spec = fundLineCall("ft.test.near", E, "18446744073709551615", 2, 1001n, H);
  assert.equal(spec.receiverId, "ft.test.near");
  assert.equal(spec.methodName, "ft_transfer_call");
  assert.equal(spec.deposit, ONE_YOCTO);
  assert.equal(spec.gas, GAS.fund);
  assert.deepEqual(Object.keys(spec.args), ["receiver_id", "amount", "msg"]);
  assert.equal(spec.args.amount, "1001");
  const msg = spec.args.msg as string;
  // funding.rs: deny_unknown_fields, version u8 == 1, agreement_id canonical u64 string, line_id <= MAX_LINE_ID, terms_hash hex32
  const funding = readFileSync(new URL("src/funding.rs", FIXTURE), "utf8");
  assert.match(funding, /deny_unknown_fields/);
  assert.match(funding, /pub const MAX_LINE_ID: u32 = 2;/);
  const j = JSON.parse(msg) as Record<string, unknown>;
  assert.deepEqual(Object.keys(j), ["version", "agreement_id", "line_id", "terms_hash"]);
  assert.equal(j.version, 1);
  assert.equal(j.agreement_id, "18446744073709551615");
  assert.equal(j.line_id, 2);
  assert.equal(j.terms_hash, H);
  assert.equal(msg, `{"version":1,"agreement_id":"18446744073709551615","line_id":2,"terms_hash":"${H}"}`);
  assert.throws(() => fundLineCall("ft.test.near", E, "18446744073709551616", 0, 1n, H));
  assert.throws(() => fundLineCall("ft.test.near", E, "01", 0, 1n, H));
  assert.throws(() => fundLineCall("ft.test.near", E, "1", 0, 1n, H.toUpperCase()));
});
